let changelogEntries=[];let latestChangelogEntry=null;let latestPublishedVersion=null;const CHANGELOG_PUBLIC_VISIBILITY_DAYS=7;function rowToChangelogEntry(row){return{id:row.id,version:row.version,title:row.title,body:row.body,publishedAt:row.published_at}}async function loadChangelogEntries(){const{data,error}=await supabaseClient.from(`changelog_entries`).select(`id, version, title, body, published_at`).eq(`published`,true).order(`published_at`,{ascending:false}).limit(50);if(error){console.error(error);changelogEntries=[];latestChangelogEntry=null;latestPublishedVersion=null;return}const all=data.map(rowToChangelogEntry);latestPublishedVersion=all.length>0?all[0].version:null;const cutoff=Date.now()-CHANGELOG_PUBLIC_VISIBILITY_DAYS*24*60*60*1e3;changelogEntries=all.filter(e=>new Date(e.publishedAt).getTime()>=cutoff);latestChangelogEntry=changelogEntries[0]||null;const link=document.getElementById(`profileChangelogLinkBtn`);if(link)link.style.display=changelogEntries.length?``:`none`}function changelogDateLabel(iso){return new Date(iso).toLocaleDateString(`fr-FR`,{day:`numeric`,month:`long`,year:`numeric`})}function isChangelogHeading(line){const t=line.trim();if(!t||t.length>60||/^[•\-*]/.test(t))return false;return t===t.toLocaleUpperCase(`fr-FR`)&&t!==t.toLocaleLowerCase(`fr-FR`)}function parseChangelogBody(body){const sections=[];let current=null;String(body||``).split(/\r?\n/).forEach(raw=>{const line=raw.trim();if(!line)return;if(isChangelogHeading(line)){current={heading:line,items:[]};sections.push(current);return}if(!current){current={heading:null,items:[]};sections.push(current)}current.items.push(line.replace(/^[•\-*]\s*/,``))});return sections.filter(s=>s.items.length>0)}const CHANGELOG_CHEVRON_SVG=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m9 6 6 6-6 6"></path></svg>`;function changelogItemsHtml(items){return`<ul class="cl-items">${items.map(i=>`<li>${escapeHtml(i)}</li>`).join(``)}</ul>`}function changelogBodyHtml(body){const sections=parseChangelogBody(body);if(!sections.some(s=>s.heading)){const items=sections.flatMap(s=>s.items);return items.length===1?`<p class="cl-text">${escapeHtml(items[0])}</p>`:changelogItemsHtml(items)}return sections.map(s=>{if(!s.heading)return changelogItemsHtml(s.items);const n=s.items.length;return`
      <details class="cl-cat">
        <summary aria-label="${escapeHtml(s.heading)}, ${n} nouveauté${n>1?`s`:``}"><span class="cl-cat-name">${escapeHtml(s.heading)}</span><span class="cl-cat-n">${n}</span><span class="cl-cat-chev">${CHANGELOG_CHEVRON_SVG}</span></summary>
        ${changelogItemsHtml(s.items)}
      </details>`}).join(``)}function changelogEntryHtml(e){return`
    <div class="changelog-entry">
      <div class="changelog-entry-head">
        <span class="changelog-version">v${escapeHtml(e.version)}</span>
        <span class="changelog-date">${changelogDateLabel(e.publishedAt)}</span>
      </div>
      <div class="changelog-title">${escapeHtml(e.title)}</div>
      <div class="changelog-body">${changelogBodyHtml(e.body)}</div>
    </div>
  `}function renderChangelogModal(){document.getElementById(`changelogList`).innerHTML=changelogEntries.length===0?`<div class="empty-state">Rien pour l'instant.</div>`:changelogEntries.map(changelogEntryHtml).join(``)}function updateVersionTag(){const tag=document.getElementById(`versionTag`);const el=document.getElementById(`versionTagValue`);if(!el)return;el.textContent=latestPublishedVersion||``;if(tag)tag.style.display=latestPublishedVersion?``:`none`}async function markChangelogSeen(){await loadActivityState();const now=new Date().toISOString();activityState.last_seen_changelog=now;const{error}=await supabaseClient.from(`user_activity_state`).upsert({user_id:currentUser.id,last_seen_changelog:now},{onConflict:`user_id`});if(error)console.error(error);document.getElementById(`changelogBtn`).classList.remove(`has-unread`);document.getElementById(`mobileTabProfile`).classList.remove(`has-unread`)}async function hasUnreadChangelog(){if(!latestChangelogEntry)return false;await loadActivityState();const since=activityState&&activityState.last_seen_changelog;if(!since)return true;return latestChangelogEntry.publishedAt>since}function openChangelogModal(){renderChangelogModal();openOverlay(`changelogOverlay`)}function closeChangelogModal(){closeOverlay(`changelogOverlay`,()=>{markChangelogSeen()})}async function initChangelog(){changelogCheckedAt=Date.now();await loadChangelogEntries();updateVersionTag();const unread=await hasUnreadChangelog();document.getElementById(`changelogBtn`).classList.toggle(`has-unread`,unread);document.getElementById(`mobileTabProfile`).classList.toggle(`has-unread`,unread);if(unread&&!(currentProfile&&currentProfile.onboarding_seen===false))openChangelogModal()}const CHANGELOG_RECHECK_MS=5*60*1e3;let changelogCheckedAt=0;async function recheckChangelogIfStale(now=Date.now()){if(typeof currentUser===`undefined`||!currentUser)return false;if(now-changelogCheckedAt<CHANGELOG_RECHECK_MS)return false;changelogCheckedAt=now;const{data,error}=await supabaseClient.from(`changelog_entries`).select(`version`).eq(`published`,true).order(`published_at`,{ascending:false}).limit(1);if(error||!data||data.length===0)return false;if(data[0].version===latestPublishedVersion)return false;await initChangelog();return true}document.addEventListener(`visibilitychange`,()=>{if(document.visibilityState===`visible`)recheckChangelogIfStale().catch(e=>console.error(e))});document.getElementById(`changelogBtn`).addEventListener(`click`,openChangelogModal);document.getElementById(`profileChangelogLinkBtn`).addEventListener(`click`,()=>{closeProfileModal();openChangelogModal()});document.getElementById(`closeChangelog`).addEventListener(`click`,closeChangelogModal);document.getElementById(`changelogOverlay`).addEventListener(`click`,e=>{if(e.target.id===`changelogOverlay`)closeChangelogModal()});